# Function to check if business is open after 6PM on at least one weekday (Mon-Fri)
WEEKDAYS = {'Monday','Tuesday','Wednesday','Thursday','Friday'}

def parse_time_to_minutes(t):
    # Examples: '6PM', '6:30PM', '12PM', '12AM', '11AM'
    t = t.strip()
    m = re.match(r'^(\d{1,2})(?::(\d{2}))?(AM|PM)$', t, re.IGNORECASE)
    if not m:
        return None
    hour = int(m.group(1))
    minute = int(m.group(2)) if m.group(2) else 0
    ampm = m.group(3).upper()
    if ampm == 'AM':
        if hour == 12: hour = 0
    else:
        if hour != 12: hour += 12
    return hour*60 + minute

def open_after_6pm_weekday(hours_list):
    if not hours_list:
        return False
    threshold = 18*60  # 6 PM
    for day, time_str in hours_list:
        if day not in WEEKDAYS:
            continue
        if time_str.lower() == 'closed':
            continue
        if 'open 24' in time_str.lower() or '24 hours' in time_str.lower():
            return True
        # split on en-dash or hyphen
        parts = re.split(r'[–\-—]', time_str)
        if len(parts) != 2:
            continue
        close = parts[1].strip()
        close_min = parse_time_to_minutes(close)
        if close_min is None:
            continue
        # Handle close times after midnight: e.g., 12AM = midnight; if close < open => crosses midnight => open past 6PM
        open_min = parse_time_to_minutes(parts[0].strip())
        # If close time is 12AM (0), that means midnight - definitely after 6 PM
        if close_min == 0:
            return True
        if open_min is not None and close_min < open_min:
            # crosses midnight - definitely open after 6PM
            return True
        if close_min > threshold:
            return True
    return False

biz['open_after_6pm_weekday'] = biz['hours_parsed'].apply(open_after_6pm_weekday)
print('Businesses open after 6PM on weekday:', biz['open_after_6pm_weekday'].sum())
print(biz[biz['open_after_6pm_weekday']][['name','hours_parsed']].head(20))

